import Foundation
@testable import JorPushCore
import XCTest

/// Megolm.decrypt against the vodozemac vectors the Android twin is tested
/// with too (android/app/src/test/resources/megolm_vectors.json, generated by
/// scripts/push/gen_megolm_vectors.py) - read in place, not copied.
final class MegolmTests: XCTestCase {
    private static let vectors: [String: Any] = {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<6 { url.deleteLastPathComponent() } // -> apps/web
        url.appendPathComponent("android/app/src/test/resources/megolm_vectors.json")
        let data = try! Data(contentsOf: url)
        return try! JSONSerialization.jsonObject(with: data) as! [String: Any]
    }()

    private func export(_ index: Int) -> String {
        (Self.vectors["exports"] as! [String: String])[String(index)]!
    }

    private func message(_ index: Int) -> (ciphertext: String, plaintext: String) {
        let m = (Self.vectors["messages"] as! [String: [String: String]])[String(index)]!
        return (m["ciphertext"]!, m["plaintext"]!)
    }

    func testDecryptsEveryMessageFromTheIndexZeroExport() throws {
        for i in [0, 1, 2, 255, 256, 257, 65535, 65536, 70000] {
            let m = message(i)
            XCTAssertEqual(try Megolm.decrypt(exportedSessionKey: export(0), ciphertext: m.ciphertext), m.plaintext, "index \(i)")
        }
    }

    func testDecryptsFromLaterExports() throws {
        for (exp, msg) in [(2, 2), (256, 257), (65536, 70000), (256, 65536)] {
            XCTAssertEqual(try Megolm.decrypt(exportedSessionKey: export(exp), ciphertext: message(msg).ciphertext),
                           message(msg).plaintext, "export \(exp), message \(msg)")
        }
    }

    func testRefusesMessagesBeforeTheKnownIndex() {
        XCTAssertThrowsError(try Megolm.decrypt(exportedSessionKey: export(256), ciphertext: message(255).ciphertext)) {
            XCTAssertTrue(String(describing: $0).contains("before"), String(describing: $0))
        }
    }

    func testRejectsATamperedMessage() {
        let tampered = Self.vectors["tampered_index1"] as! String
        XCTAssertThrowsError(try Megolm.decrypt(exportedSessionKey: export(0), ciphertext: tampered))
    }

    func testVerifiesTheEd25519Signature() throws {
        // MAC intact, only the trailing signature altered.
        var raw = try Megolm.unbase64(message(1).ciphertext)
        raw[raw.count - 1] ^= 1
        let forged = raw.base64EncodedString().replacingOccurrences(of: "=", with: "")
        XCTAssertThrowsError(try Megolm.decrypt(exportedSessionKey: export(0), ciphertext: forged)) {
            XCTAssertEqual(($0 as? Megolm.DecryptionError)?.description, "bad signature")
        }
    }

    func testRejectsGarbage() {
        XCTAssertThrowsError(try Megolm.decrypt(exportedSessionKey: "AAAA", ciphertext: "AAAA"))
        XCTAssertThrowsError(try Megolm.decrypt(exportedSessionKey: "not base64!", ciphertext: "x"))
    }

    func testBase64AcceptsPaddedUnpaddedAndUrlSafe() throws {
        XCTAssertEqual(String(decoding: try Megolm.unbase64("aGVsbG8"), as: UTF8.self), "hello")
        XCTAssertEqual(String(decoding: try Megolm.unbase64("aGVsbG8="), as: UTF8.self), "hello")
        XCTAssertEqual(try Megolm.unbase64("-_8"), try Megolm.unbase64("+/8="))
    }

    func testFirstIndexReadsTheExportHeader() {
        XCTAssertEqual(PushStore.firstIndex(export(0)), 0)
        XCTAssertEqual(PushStore.firstIndex(export(256)), 256)
        XCTAssertEqual(PushStore.firstIndex(export(65536)), 65536)
        XCTAssertEqual(PushStore.firstIndex("??"), .max)
    }
}

final class DescribeTests: XCTestCase {
    private func describe(_ type: String, _ content: [String: Any], membership: String = "") -> String {
        PushResolver.describe(type: type, content: content, membership: membership, senderName: "Sofia", texts: .en)
    }

    func testTextMessagesShowTheirBody() {
        XCTAssertEqual(describe("m.room.message", ["msgtype": "m.text", "body": "szia!"]), "szia!")
    }

    func testRepliesDropTheQuoteFallback() {
        let body = "> <@ava:example.org> original\n> more\n\nthe answer"
        XCTAssertEqual(describe("m.room.message", ["msgtype": "m.text", "body": body]), "the answer")
    }

    func testSpecialTypes() {
        XCTAssertEqual(describe("m.room.message", ["msgtype": "m.emote", "body": "waves"]), "* Sofia waves")
        XCTAssertEqual(describe("m.room.message", ["msgtype": "m.image", "body": "IMG_1.jpg"]), "🖼 Image")
        XCTAssertEqual(describe("m.room.member", [:], membership: "invite"), "invited you")
        XCTAssertEqual(describe("m.call.invite", [:]), "Incoming call")
        XCTAssertEqual(describe("m.sticker", ["body": "cat"]), "Sticker")
        XCTAssertEqual(describe("org.matrix.msc3381.poll.start", [:]), "📊 Poll")
        XCTAssertEqual(describe("m.room.encrypted", [:]), "Encrypted message")
        XCTAssertEqual(describe("m.reaction", [:]), "New message")
    }

    func testLanguagePick() {
        XCTAssertEqual(PushTexts.forLanguage("hu-HU"), .hu)
        XCTAssertEqual(PushTexts.forLanguage("en-GB"), .en)
        XCTAssertEqual(PushTexts.forLanguage("de"), .en)
        XCTAssertEqual(PushTexts.forLanguage(nil), .en)
    }
}
